#!/usr/bin/env bash
# Re-vendor gate/ from the source of truth in xchk-app, then regenerate
# MANIFEST.sha256 over every executable surface of the package. Heads are
# packaging, never forks — do not edit gate/ files in this repo.
#
# Release checklist (Tier 1+2):
#   1. ./scripts/sync-gate.sh
#   2. git commit
#   3. git tag -s vX.Y.Z -m "xchk-plugin vX.Y.Z"   # SIGNED tag, always
#   4. git push --follow-tags
#   5. XCHK_ADMIN_TOKEN=... ./scripts/publish-release.sh   # known-good manifest
#      to the registry. Without this the gate's self-hash has nothing to be
#      contradicted against, and every install reports 'unknown-version'.
#   6. Installs pin the tag: `hermes plugins install minitru/xchk-plugin@vX.Y.Z`;
#      Claude marketplace entries reference the tagged commit SHA. Never main.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SRC="${XCHK_APP:-/Volumes/2TB-FAST/sean-overflow/src/xchk/xchk-app}/examples/claude-attestation-guardrails"
cp "$SRC/hooks/xchk_hook.py" "$ROOT/gate/xchk_hook.py"
cp "$SRC/xchk_client.py" "$ROOT/gate/xchk_client.py"
cp "$SRC/xchk_labels.py" "$ROOT/gate/xchk_labels.py"
# ONE DETECTOR (27 Sep 2026): the Hermes gate carries its own copy of the injection detector; it was only ever in step by
# hand. Refresh it from the same source on every sync so every harness screens with the same bytes.
HERMES_DIR="$(dirname "$SRC")/hermes-attestation-guardrails"
[[ -d "$HERMES_DIR" ]] && cp "$SRC/xchk_labels.py" "$HERMES_DIR/xchk_labels.py"
# The UserPromptSubmit intent hook joined the release 12 Sep 2026: it used to be hand-placed
# and every re-fit wiped it (gap GR-2). Present in the source tree = shipped; absent = skipped.
[[ -f "$SRC/hooks/xchk_prompt_hook.py" ]] && cp "$SRC/hooks/xchk_prompt_hook.py" "$ROOT/gate/xchk_prompt_hook.py"
# The context handoff screen (17 Sep 2026) rides the same way: present in the source tree = shipped.
[[ -f "$SRC/hooks/xchk_compact_screen.py" ]] && cp "$SRC/hooks/xchk_compact_screen.py" "$ROOT/gate/xchk_compact_screen.py"
python3 - "$ROOT" "$SRC" <<'EOF'
import ast, hashlib, pathlib, sys
root = pathlib.Path(sys.argv[1])
for p in root.glob("gate/*.py"):
    ast.parse(p.read_text())
# Every file whose bytes participate in enforcement or agent-visible behavior.
COVERED = sorted([
    *root.glob("gate/*.py"),
    # cursor/ wires the same gate into Cursor's own hooks.json. It decides
    # WHICH events reach the gate, so its bytes decide coverage as surely as
    # the gate's do — a silently edited installer could drop preToolUse and
    # leave a live plate gating nothing.
    *root.glob("cursor/*.py"),
    root / "hooks/hooks.json",
    root / "mcp/xchk_mcp.py",
    *sorted(root.glob("skills/*/SKILL.md")),
    root / ".claude-plugin/plugin.json",
    root / "plugin.json",
    root / "mcp.json",
    root / ".mcp.json",
])
lines = ["# xchk-plugin release manifest — regenerated by scripts/sync-gate.sh",
         "# The gate self-hashes against this file and reports the verdict in",
         "# its status ping (self-attested; issuer holds the known-good copy)."]
for p in COVERED:
    lines.append(f"{hashlib.sha256(p.read_bytes()).hexdigest()}  {p.relative_to(root)}")
(root / "MANIFEST.sha256").write_text("\n".join(lines) + "\n")
print(f"gate/ synced; MANIFEST.sha256 covers {len(COVERED)} files")

# The STANDALONE manifest: what install-claude-xchk.sh actually lays down.
#
# That installer places the hook at hooks/xchk_hook.py and the client at the
# root — two files, not the eleven of the full package. Handing it the plugin
# manifest would report "modified" for nine files it was never meant to have,
# on every install, which is a false alarm loud enough to teach people to
# ignore the real one. So the issuer publishes a manifest for that tree too,
# generated HERE at release time rather than minted on the host, which is the
# whole difference between "these are the bytes we shipped" and "these are the
# bytes that arrived".
STANDALONE = [("hooks/xchk_hook.py", root / "gate/xchk_hook.py"),
              ("xchk_client.py",     root / "gate/xchk_client.py"),
              ("xchk_labels.py",     root / "gate/xchk_labels.py")]
# the prompt hook rides the standalone tree only when the release carries it
if (root / "gate/xchk_prompt_hook.py").is_file():
    STANDALONE.insert(1, ("hooks/xchk_prompt_hook.py", root / "gate/xchk_prompt_hook.py"))
if (root / "gate/xchk_compact_screen.py").is_file():
    STANDALONE.append(("hooks/xchk_compact_screen.py", root / "gate/xchk_compact_screen.py"))
slines = ["# xchk standalone gate manifest — regenerated by scripts/sync-gate.sh",
          "# Covers the tree install-claude-xchk.sh lays down (hook + client + labels).",
          "# Issuer-generated: the registry holds the known-good copy."]
for rel, src in STANDALONE:
    slines.append(f"{hashlib.sha256(src.read_bytes()).hexdigest()}  {rel}")
standalone_text = "\n".join(slines) + "\n"
(root / "MANIFEST.standalone.sha256").write_text(standalone_text)
# install-claude-xchk.sh fetches this manifest from the xchk-app tree, so the
# copy that actually ships is the one over there. Writing only the plugin copy
# left the served manifest to be maintained by hand, and the two drifted.
if len(sys.argv) > 2:
    src_manifest = pathlib.Path(sys.argv[2]) / "MANIFEST.standalone.sha256"
    if src_manifest.parent.is_dir():
        src_manifest.write_text(standalone_text)
        print(f"MANIFEST.standalone.sha256 covers {len(STANDALONE)} files (plugin + src)")
    else:
        print(f"MANIFEST.standalone.sha256 covers {len(STANDALONE)} files (plugin only)")
else:
    print(f"MANIFEST.standalone.sha256 covers {len(STANDALONE)} files (plugin only)")
EOF
